// Subscribe before sending. Keep the original mount pending on failure, with
// an explicit retry; do not enter the game with an absent character snapshot.
function r6JoinRoom() {
    return new Promise(resolve => {
        let timer = null, panel = null, pending = false, finished = false;
        let receivedState = false, receivedAck = false;
        const off = [];
        function hide() {
            if (panel) panel.remove();
            panel = null;
        }
        function clearTimer() {
            if (timer !== null) clearTimeout(timer);
            timer = null;
        }
        function fail(message) {
            if (finished) return;
            pending = false;
            clearTimer();
            hide();
            panel = document.createElement("section");
            panel.className = "r6-init-error";
            panel.setAttribute("role", "alert");
            const title = document.createElement("strong");
            title.textContent = "角色加载未完成";
            const detail = document.createElement("p");
            detail.textContent = message || "暂时无法加载角色，请稍后重试。";
            const retry = document.createElement("button");
            retry.type = "button";
            retry.textContent = "重试加载";
            retry.onclick = start;
            const login = document.createElement("a");
            login.href = "/login";
            login.textContent = "返回登录";
            panel.append(title, detail, retry, login);
            document.body.append(panel);
        }
        function complete() {
            if (finished || !receivedState || !receivedAck) return;
            finished = true;
            clearTimer();
            hide();
            off.forEach(stop => stop());
            resolve();
        }
        function send() { ip("joinRoom", {}); }
        function start() {
            if (pending || finished) return;
            pending = true;
            receivedState = receivedAck = false;
            hide();
            clearTimer();
            timer = setTimeout(() => fail("服务器响应超时，请稍后重试加载。"), 20000);
            if (ap.connected) send();
            else ap.connect();
        }
        off.push(up("characterInitData")(payload => {
            if (!payload || !payload.data || typeof payload.data !== "object") return;
            receivedState = true;
            complete();
        }));
        off.push(up("join-room:success")(() => { receivedAck = true; complete(); }));
        for (const name of ["joinRoom:error", "joinRoom:fail", "joinRoom:failed"]) {
            off.push(up(name)(payload => fail(payload?.message || payload?.msg)));
        }
        const connect = () => { if (pending) send(); };
        const disconnect = () => fail("与服务器的连接已断开，请重试加载。");
        ap.on("connect", connect);
        ap.on("disconnect", disconnect);
        off.push(() => ap.off("connect", connect), () => ap.off("disconnect", disconnect));
        start();
    });
}

// This function lives in the original module and uses its authenticated socket.
let r6ServicePending = null;
function r6OpenHomeService() {
    if (document.getElementById("r6-home-service")) return;
    const dialog = document.createElement("dialog");
    dialog.id = "r6-home-service";
    dialog.setAttribute("aria-label", "家政服务");
    dialog.style.cssText = "width:min(440px,90vw);box-sizing:border-box;padding:24px;border:1px solid #dcdfe6;border-radius:12px;color:var(--el-text-color-primary,#303133);background:var(--el-bg-color,#fff);box-shadow:0 12px 40px #0003";
    dialog.innerHTML = `<form method="dialog" style="float:right"><button aria-label="关闭">关闭</button></form>
      <h2 style="margin:0 0 20px">家政服务</h2><p data-status role="status">读取中…</p>
      <p data-expiry></p><p data-fee></p><p data-funds></p>
      <p style="line-height:1.7;font-size:13px;color:#909399">全镇共同筹集维护费，筹满后续期一个周期。欠费期间暂停自动收获补种及家具维修，手动操作仍可使用；补缴后从恢复时刻继续服务。</p>
      <label>捐助金币 <input data-count type="number" min="1" step="1" style="width:140px;padding:6px"></label>
      <p><button data-pay type="button" style="padding:8px 18px;background:#409eff;border:0;border-radius:4px;color:white" disabled>捐助维护费</button>
      <button data-refresh type="button" style="margin-left:8px;padding:7px">刷新</button></p><p data-message role="alert"></p>`;
    const find = s => dialog.querySelector(s), amount = find("[data-count]"), pay = find("[data-pay]"), msg = find("[data-message]");
    let current = null, waiting = false, timer = null, amountEdited = false;
    amount.oninput = () => { amountEdited = true; };
    const show = (selector, text) => { find(selector).textContent = text; };
    const buttons = () => {
        amount.disabled = waiting || !!r6ServicePending;
        pay.disabled = waiting || (!r6ServicePending && (!current || current.level < 1 || !current.cycleDays || !current.needed?.gold));
        pay.textContent = waiting ? "提交中…" : r6ServicePending ? "重试这笔捐助" : "捐助维护费";
    };
    const render = value => {
        current = value;
        show("[data-status]", value.level < 1 ? "家政服务中心尚未建成" : value.active ? "服务生效中" : "维护费不足，服务已暂停");
        show("[data-expiry]", value.level > 0 && value.paidUntil ? "服务有效期至：" + new Date(value.paidUntil).toLocaleString() : "请先到镇中心建设家政服务中心。");
        show("[data-fee]", `维护周期：${value.cycleDays} 天 · 每期 ${(value.fee?.gold || 0).toLocaleString()} 金币`);
        show("[data-funds]", `本期已筹集 ${(value.funds?.gold || 0).toLocaleString()} · 还需 ${(value.needed?.gold || 0).toLocaleString()} 金币`);
        amount.max = String(value.needed?.gold || 0);
        if (r6ServicePending) amount.value = String(r6ServicePending.count);
        else if (!amountEdited) amount.value = String(value.needed?.gold || 1);
        buttons();
    };
    const listeners = [
        up("homeService:status:success")(render),
        up("homeService:status:error")(v => { msg.textContent = v.message || v.msg || "读取失败，请重试"; }),
        up("homeService:donate:success")(v => {
            // A timed-out request can yield two replies. An old reply must
            // never acknowledge a newer donation or discard its retry key.
            if (!r6ServicePending || v.requestId !== r6ServicePending.requestId) return;
            clearTimeout(timer); waiting = false; r6ServicePending = null;
            amountEdited = false;
            render(v); msg.textContent = "捐助成功，感谢支持！";
        }),
        up("homeService:donate:error")(v => {
            if (!r6ServicePending || (v.requestId && v.requestId !== r6ServicePending.requestId)) return;
            clearTimeout(timer); waiting = false;
            msg.textContent = v.message || v.msg || "提交失败，请稍后重试";
            // An internal error can occur after commit while sending the reply.
            // Keep the idempotency key for safe retries in that case.
            if (v.requestId && msg.textContent !== "服务器开小差了") r6ServicePending = null;
            buttons();
        })
    ];
    pay.onclick = () => {
        if (waiting) return;
        if (!r6ServicePending) {
            const count = Number(amount.value);
            if (!Number.isSafeInteger(count) || count < 1 || count > (current?.needed?.gold || 0)) {
                msg.textContent = "请输入不超过剩余维护费的正整数"; return;
            }
            const bytes = crypto.getRandomValues(new Uint8Array(16));
            bytes[6] = bytes[6] & 15 | 64; bytes[8] = bytes[8] & 63 | 128;
            const hex = Array.from(bytes, b => b.toString(16).padStart(2, "0")).join("");
            r6ServicePending = {count, requestId: `${hex.slice(0,8)}-${hex.slice(8,12)}-${hex.slice(12,16)}-${hex.slice(16,20)}-${hex.slice(20)}`};
        }
        waiting = true; msg.textContent = ""; buttons();
        timer = setTimeout(() => { waiting = false; msg.textContent = "尚未收到结果，可重试同一笔捐助，不会重复扣款。"; buttons(); }, 12000);
        try { ip("homeService:donate", r6ServicePending); }
        catch (_) {
            clearTimeout(timer); waiting = false;
            msg.textContent = "连接异常，可安全重试同一笔捐助。"; buttons();
        }
    };
    find("[data-refresh]").onclick = () => ip("homeService:status", {});
    dialog.addEventListener("close", () => { clearTimeout(timer); listeners.forEach(off => off()); dialog.remove(); }, {once:true});
    document.body.append(dialog); dialog.showModal();
    if (r6ServicePending) {
        amount.value = String(r6ServicePending.count);
        msg.textContent = "上次提交结果尚未确认，可安全重试同一笔捐助。";
    }
    buttons();
    ip("homeService:status", {});
}
